<script setup lang="ts">
import { computed,ref } from 'vue'
import { contextBudget,cosineDistance,evidenceCheck,approvalValid,confusion } from '../lib/aiLearningLabs'
const props=defineProps<{moduleId:string}>()
const mode=computed(()=>props.moduleId==='ai-tokens-context'?'budget':/embeddings|hybrid-ranking|pgvector|retrieval-evaluation/.test(props.moduleId)?'retrieval':/grounded-answer|structured-results|uncertainty/.test(props.moduleId)?'evidence':/approval-actions|durable-agents/.test(props.moduleId)?'approval':/evaluation|calibration|regression/.test(props.moduleId)?'eval':'')
const history=ref(140),evidence=ref(300)
const budget=computed(()=>contextBudget([120,180,60,history.value,evidence.value],200,1000))
const scope=ref(true),query=ref('dispatch')
const docs=[{id:'D1',tenant:'A',title:'Dispatch delay policy',vector:[1,.1]},{id:'D2',tenant:'A',title:'Refund delay policy',vector:[.2,1]},{id:'D3',tenant:'B',title:'Other tenant: exact-looking dispatch guide',vector:[1,0]}]
const neighbors=computed(()=>docs.filter(d=>!scope.value||d.tenant==='A').map(d=>({...d,distance:cosineDistance(query.value==='dispatch'?[1,0]:[0,1],d.vector)})).sort((a,b)=>a.distance-b.distance))
const citation=ref('F1'),field=ref('held_count'),value=ref(2)
const check=computed(()=>evidenceCheck(citation.value,field.value,value.value))
const version=ref(3),changed=ref(false),expired=ref(false)
const approval=computed(()=>approvalValid({digest:'shipment-14:review-note',version:3,expires:100},{digest:changed.value?'shipment-15:review-note':'shipment-14:review-note',version:version.value,now:expired.value?101:10}))
const threshold=ref(70)
const scores=[{score:.95,correct:true},{score:.9,correct:false},{score:.8,correct:true},{score:.65,correct:true},{score:.5,correct:false},{score:.2,correct:false}]
const metrics=computed(()=>confusion(scores,threshold.value/100))
</script>
<template>
 <section v-if="mode" class="sw-card ai-sandbox" aria-label="AI mechanism sandbox">
  <p class="sw-eyebrow">Change one thing · predict before comparing</p><h2>Make the boundary visible</h2><p class="sw-muted">A deterministic model with synthetic values. It does not call an LLM or execute a real integration.</p>
  <template v-if="mode==='budget'"><h3>Pack a request into 1,000 teaching units</h3><p>Fixed: instructions 120 + tools 180 + question 60. Reserve: 200 output. These are invented units, not tokenizer measurements.</p><label class="sw-label">History · {{ history }}<input v-model.number="history" type="range" min="0" max="800" step="20"/></label><label class="sw-label">Evidence · {{ evidence }}<input v-model.number="evidence" type="range" min="0" max="800" step="20"/></label><div class="ai-meter"><span :style="{width:Math.min(100,budget.used/10)+'%'}"/></div><p role="status">{{ budget.used }}/1,000 used · {{ budget.fits?`${budget.remaining} available`:`${-budget.remaining} over budget` }}</p><p>What would you shorten without removing the policy or separating a tool call from its result?</p></template>
  <template v-else-if="mode==='retrieval'"><h3>Nearest does not mean permitted</h3><p>Two-dimensional, hand-made vectors. This illustrates distance and scope, not learned semantic quality.</p><label class="sw-label">Question<select v-model="query"><option value="dispatch">Dispatch delay</option><option value="refund">Refund delay</option></select></label><label class="sw-checkbox"><input v-model="scope" type="checkbox"/>Apply the authenticated tenant A scope before returning evidence</label><ol><li v-for="d in neighbors" :key="d.id">{{ d.id }} · {{ d.title }} · distance {{ d.distance.toFixed(3) }}</li></ol><p role="status">{{ scope?'Only tenant A candidates may be used.':'Unsafe experiment: the other tenant can now appear. These are synthetic records.' }}</p><p>Rank can improve while access becomes wrong. Keep those checks separate.</p></template>
  <template v-else-if="mode==='evidence'"><h3>A valid source ID can still support the wrong claim</h3><p>Supplied fact F1: held_count = 2.</p><label class="sw-label">Citation<select v-model="citation"><option>F1</option><option>F9</option></select></label><label class="sw-label">Claimed field<select v-model="field"><option value="held_count">held_count</option><option value="released_count">released_count</option></select></label><label class="sw-label">Claimed value<select v-model.number="value"><option :value="2">2</option><option :value="9">9</option></select></label><p role="status">Source exists: {{ check.knownSource?'yes':'no' }} · exact field/value agrees: {{ check.exactField?'yes':'no' }}</p><p>This validates a narrow typed claim. It does not prove arbitrary prose is supported. Try released_count = 2 with F1.</p></template>
  <template v-else-if="mode==='approval'"><h3>Approval is for one exact operation</h3><p>The user approved a review note on shipment 14 at version 3.</p><label class="sw-label">Current record version<select v-model.number="version"><option :value="3">3</option><option :value="4">4</option></select></label><label class="sw-checkbox"><input v-model="changed" type="checkbox"/>Change the target to shipment 15</label><label class="sw-checkbox"><input v-model="expired" type="checkbox"/>Let approval expire</label><p role="status">{{ approval?'This operation still matches the approval. Current permissions must also pass.':'Approval no longer matches. Rebuild the preview and obtain new approval.' }}</p><p>No action is executed here. Approval, authorization, idempotency and outcome tracking are separate gates.</p></template>
  <template v-else><h3>Change a threshold; inspect the mistakes</h3><p>Six fixed teaching cases include a wrong answer scored 0.90. These scores are invented and uncalibrated.</p><label class="sw-label">Accept score at least {{ threshold }}%<input v-model.number="threshold" type="range" min="0" max="100" step="5"/></label><p role="status">Correct accepts {{ metrics.tp }} · wrong accepts {{ metrics.fp }} · correct rejected {{ metrics.fn }} · wrong rejected {{ metrics.tn }}</p><p>Precision: {{ metrics.precision===null?'undefined (no accepts)':(metrics.precision*100).toFixed(0)+'%' }} · recall: {{ metrics.recall===null?'undefined':(metrics.recall*100).toFixed(0)+'%' }}</p><p>A threshold changes a decision policy. It does not make an uncalibrated score truthful.</p></template>
 </section>
</template>
<style scoped>.ai-sandbox{border-color:var(--accent-cyan)}.ai-sandbox input[type=range]{display:block;width:100%;max-width:540px;accent-color:var(--accent-cyan);margin:14px 0}.ai-sandbox select{display:block;width:100%;max-width:540px;margin-top:8px}.ai-meter{height:16px;background:var(--bg-primary);border:1px solid var(--border-default);border-radius:8px;overflow:hidden}.ai-meter span{display:block;height:100%;background:var(--accent-cyan)}li{line-height:1.7;margin:12px 0;overflow-wrap:anywhere}</style>
